with p as (select * from jsonb_to_recordset($v6$[{"race_key":"2026-11-08/京都/12","horse_no":15,"horse_name":"クールフラン","horse_id":"2023106985","target_date":"2026-11-08","post_time":"2026-11-08 07:25:00+00"},{"race_key":"2026-11-14/京都/8","horse_no":1,"horse_name":"レゼルフォート","horse_id":"2023106935","target_date":"2026-11-14","post_time":"2026-11-14 04:55:00+00"},{"race_key":"2026-11-14/京都/10","horse_no":5,"horse_name":"ショウナンラプンタ","horse_id":"2021105195","target_date":"2026-11-14","post_time":"2026-11-14 06:05:00+00"},{"race_key":"2026-11-14/京都/10","horse_no":6,"horse_name":"アスクカムオンモア","horse_id":"2021105236","target_date":"2026-11-14","post_time":"2026-11-14 06:05:00+00"},{"race_key":"2026-11-14/京都/10","horse_no":7,"horse_name":"グランヴィノス","horse_id":"2020103522","target_date":"2026-11-14","post_time":"2026-11-14 06:05:00+00"},{"race_key":"2026-11-14/京都/10","horse_no":13,"horse_name":"ジャスティンビスタ","horse_id":"2023102807","target_date":"2026-11-14","post_time":"2026-11-14 06:05:00+00"},{"race_key":"2026-11-14/東京/10","horse_no":2,"horse_name":"フクチャンショウ","horse_id":"2023103418","target_date":"2026-11-14","post_time":"2026-11-14 05:55:00+00"}]$v6$::jsonb) as p(race_key text,horse_no int,horse_name text,horse_id text,target_date date,post_time timestamptz))
select p.*,a.id race_id,s.id run_id,a.race_date,a.track,a.race_no,a.race_type,a.class_name,a.surface,a.distance,a.field_size,a.source_ref,a.source_checked_at,a.created_at,a.updated_at,s.horse_name,s.horse_ref,s.finish,s.final3f,
(a.source_checked_at<p.post_time and a.created_at<p.post_time and a.updated_at<p.post_time) as source_asof_ok
from p join public.jra_lab_runs s on substring(s.horse_ref from 'pw01dud[0-9]{2}([0-9]{10})/')=p.horse_id and s.horse_name=p.horse_name and s.record_role='full_runner' join public.jra_lab_races a on a.id=s.race_id and a.race_date<p.target_date and a.race_date>=p.target_date-540
order by p.race_key,p.horse_no,a.race_date desc,a.id,s.id;
